\begin{theorem}
For $r \neq 1$,
\begin{equation}
  S_n = \sum_{k=0}^{n-1} r^k = \frac{1 - r^n}{1 - r}.
\end{equation}
\end{theorem}

\begin{proof}
Since
\begin{align}
  S_n - r S_n &= (1 + r + \cdots + r^{n-1}) - (r + r^2 + \cdots + r^n) \\
              &= 1 - r^n,
\end{align}
dividing by $1 - r$ gives the claim.
\end{proof}
